INSERT INTO modelo (id, marca_id, nombre, tipo_carroceria, anio, descripcion, destacado) VALUES
  (1, 1, 'Corolla', 'SEDAN', 2026, 'El sedán mediano más vendido del mundo. Andar suave, consumo bajo y una versión híbrida que en ciudad usa el motor eléctrico buena parte del tiempo.', TRUE),
  (2, 1, 'Corolla Cross', 'SUV', 2026, 'SUV compacto con la mecánica del Corolla, más altura libre y un baúl de 440 litros. Disponible con motor naftero o híbrido.', TRUE),
  (3, 1, 'Hilux', 'PICKUP', 2026, 'La pickup de referencia en el país. Cabina doble, tracción 4x4 con reductora y la versión GR-Sport con suspensión recalibrada.', TRUE),
  (4, 1, 'Yaris', 'HATCHBACK', 2026, 'Hatchback urbano, fácil de estacionar y de mantener. Caja CVT de serie en todas las versiones.', FALSE),
  (5, 2, 'Amarok', 'PICKUP', 2026, 'Nueva generación de la pickup de Volkswagen. La V6 de 258 CV es de las más potentes del segmento.', TRUE),
  (6, 2, 'Taos', 'SUV', 2026, 'SUV mediano con buen espacio atrás y motor turbo de 150 CV. Pensado para familia y ruta.', FALSE),
  (7, 2, 'T-Cross', 'SUV', 2026, 'SUV chico fabricado en la región. Posición de manejo alta, asiento trasero deslizable y motores turbo.', TRUE),
  (8, 2, 'Polo', 'HATCHBACK', 2026, 'Hatchback compacto con buena terminación y comportamiento firme. Opción manual o automática.', FALSE),
  (9, 3, 'A3 Sedan', 'SEDAN', 2026, 'Sedán compacto premium con caja de doble embrague y una versión S3 de 310 CV con tracción quattro.', TRUE),
  (10, 3, 'Q3', 'SUV', 2026, 'SUV premium compacto, interior digital y opción de tracción quattro.', FALSE),
  (11, 4, 'Serie 3', 'SEDAN', 2026, 'El sedán deportivo de BMW: tracción trasera, reparto de pesos 50/50 y caja automática de 8 marchas.', TRUE),
  (12, 4, 'X1', 'SUV', 2026, 'SUV de entrada de BMW, de nueva generación, con pantalla curva y mucho espacio interior para su tamaño.', FALSE),
  (13, 5, 'Onix', 'HATCHBACK', 2026, 'Uno de los autos más vendidos del país. Motor 1.0 turbo con buen consumo y conectividad de serie.', TRUE),
  (14, 5, 'Tracker', 'SUV', 2026, 'SUV compacto con motor 1.2 turbo, seis airbags de serie y la versión Premier con techo panorámico.', FALSE),
  (15, 5, 'S10', 'PICKUP', 2026, 'Pickup mediana con motor 2.8 turbodiésel de 200 CV. Versión High Country con tracción 4x4 y caja automática.', FALSE);
