-- Los IDs se cargaron a mano: se ajustan las secuencias para que los próximos INSERT no choquen.
SELECT setval(pg_get_serial_sequence('marca', 'id'), (SELECT MAX(id) FROM marca));
SELECT setval(pg_get_serial_sequence('modelo', 'id'), (SELECT MAX(id) FROM modelo));
SELECT setval(pg_get_serial_sequence('version', 'id'), (SELECT MAX(id) FROM version));
